FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on:
// (Dual polyhedrons)
// https://en.wikipedia.org/wiki/Deltoidal_icositetrahedron
// https://en.wikipedia.org/wiki/Rhombicuboctahedron
float hgsdfDeltoidalIcositetrahedronSoft(vec3 p, float r, float e)
{
    const float a = 1.0 + sqrt(2.0);

    // From: https://en.wikipedia.org/wiki/Rhombicuboctahedron
    // "Cartesian coordinates of a rhombicuboctahedron with an edge length 2 are the permutations of:"
    const vec3 v0 = normalize(vec3( a,    1,    1));
    const vec3 v1 = normalize(vec3( a,    1,   -1));
    const vec3 v2 = normalize(vec3( a,   -1,    1));
    const vec3 v3 = normalize(vec3( a,   -1,   -1));
    const vec3 v4 = normalize(vec3(-a,    1,    1));
    const vec3 v5 = normalize(vec3(-a,    1,   -1));
    const vec3 v6 = normalize(vec3(-a,   -1,    1));
    const vec3 v7 = normalize(vec3(-a,   -1,   -1));

    float d = 0.0;

    d += pow(abs(dot(p, v0)), e);
    d += pow(abs(dot(p, v1)), e);
    d += pow(abs(dot(p, v2)), e);
    d += pow(abs(dot(p, v3)), e);
    d += pow(abs(dot(p, v4)), e);
    d += pow(abs(dot(p, v5)), e);
    d += pow(abs(dot(p, v6)), e);
    d += pow(abs(dot(p, v7)), e);

    d += pow(abs(dot(p, v0.yxz)), e);
    d += pow(abs(dot(p, v1.yxz)), e);
    d += pow(abs(dot(p, v2.yxz)), e);
    d += pow(abs(dot(p, v3.yxz)), e);
    d += pow(abs(dot(p, v4.yxz)), e);
    d += pow(abs(dot(p, v5.yxz)), e);
    d += pow(abs(dot(p, v6.yxz)), e);
    d += pow(abs(dot(p, v7.yxz)), e);

    d += pow(abs(dot(p, v0.yzx)), e);
    d += pow(abs(dot(p, v1.yzx)), e);
    d += pow(abs(dot(p, v2.yzx)), e);
    d += pow(abs(dot(p, v3.yzx)), e);
    d += pow(abs(dot(p, v4.yzx)), e);
    d += pow(abs(dot(p, v5.yzx)), e);
    d += pow(abs(dot(p, v6.yzx)), e);
    d += pow(abs(dot(p, v7.yzx)), e);

    return pow(d, 1./e) - r;
}
